// @ts-check
import { test, expect } from "@playwright/test";

/**
 * Supabase Auth email links (T6.07; D-03).
 *
 * The links are generated by Supabase and land on /auth/callback with the
 * session in the URL fragment. These journeys prove the page stores that
 * session, removes the fragment, updates a recovery password, and reports an
 * expired or malformed link. The Supabase endpoint is intercepted so the
 * credential-free suite never contacts the live project.
 */

const SESSION_KEY = "velaris.auth.session.v1";
const ACCESS_TOKEN = "recovery-access-token";
const REFRESH_TOKEN = "recovery-refresh-token";

function authHeaders() {
  return {
    "access-control-allow-origin": "*",
    "access-control-allow-methods": "GET, POST, PUT, OPTIONS",
    "access-control-allow-headers": "authorization, apikey, content-type",
    "content-type": "application/json",
  };
}

test.describe("Supabase Auth email links (D-03)", () => {
  test("accepts a recovery link and updates the password", async ({ page }) => {
    let payload = null;
    let authorization = null;
    await page.route("**/auth/v1/user*", async (route) => {
      if (route.request().method() === "OPTIONS") {
        await route.fulfill({ status: 204, headers: authHeaders() });
        return;
      }
      payload = route.request().postDataJSON();
      authorization = route.request().headers()["authorization"];
      await route.fulfill({
        status: 200,
        headers: authHeaders(),
        body: JSON.stringify({ id: "user-recovery" }),
      });
    });

    await page.goto(
      `/auth/callback#access_token=${ACCESS_TOKEN}&refresh_token=${REFRESH_TOKEN}&expires_at=4102444800&type=recovery`,
    );

    await expect(
      page.getByRole("heading", { name: "Choose a new password" }),
    ).toBeVisible();
    expect(page.url()).not.toContain("access_token");

    await page.getByTestId("new-password").fill("new-password-9");
    await page.getByTestId("confirm-password").fill("new-password-9");
    await page.getByTestId("update-password").click();

    await expect(
      page.getByRole("heading", { name: "Password updated" }),
    ).toBeVisible();
    await expect(page.getByRole("status")).toContainText("Password updated");
    expect(payload).toEqual({ password: "new-password-9" });
    expect(authorization).toBe(`Bearer ${ACCESS_TOKEN}`);

    const stored = await page.evaluate(
      (key) => JSON.parse(window.localStorage.getItem(key) ?? "null"),
      SESSION_KEY,
    );
    expect(stored?.accessToken).toBe(ACCESS_TOKEN);
    expect(stored?.refreshToken).toBe(REFRESH_TOKEN);
  });

  test("rejects mismatched passwords before any request", async ({ page }) => {
    let calls = 0;
    await page.route("**/auth/v1/user*", async (route) => {
      calls += 1;
      await route.fulfill({
        status: 200,
        headers: authHeaders(),
        body: "{}",
      });
    });

    await page.goto(
      `/auth/callback#access_token=${ACCESS_TOKEN}&refresh_token=${REFRESH_TOKEN}&expires_at=4102444800&type=recovery`,
    );
    await page.getByTestId("new-password").fill("new-password-9");
    await page.getByTestId("confirm-password").fill("different-password-9");
    await page.getByTestId("update-password").click();

    await expect(page.locator("main").getByRole("alert")).toContainText(
      "The two passwords do not match",
    );
    expect(calls).toBe(0);
  });

  test("stores the session for a confirmation link", async ({ page }) => {
    await page.goto(
      `/auth/callback#access_token=${ACCESS_TOKEN}&refresh_token=${REFRESH_TOKEN}&expires_at=4102444800&type=signup`,
    );

    await expect(
      page.getByRole("heading", { name: "Email confirmed" }),
    ).toBeVisible();
    const stored = await page.evaluate(
      (key) => JSON.parse(window.localStorage.getItem(key) ?? "null"),
      SESSION_KEY,
    );
    expect(stored?.accessToken).toBe(ACCESS_TOKEN);
  });

  test("accepts an invitation link and offers the password form", async ({
    page,
  }) => {
    await page.goto(
      `/auth/callback#access_token=${ACCESS_TOKEN}&refresh_token=${REFRESH_TOKEN}&expires_at=4102444800&type=invite`,
    );

    await expect(
      page.getByRole("heading", { name: "Choose a new password" }),
    ).toBeVisible();
    const stored = await page.evaluate(
      (key) => JSON.parse(window.localStorage.getItem(key) ?? "null"),
      SESSION_KEY,
    );
    expect(stored?.accessToken).toBe(ACCESS_TOKEN);
  });

  test("shows an actionable message for an expired link", async ({ page }) => {
    await page.goto(
      "/auth/callback#error=access_denied&error_description=Email+link+is+invalid+or+has+expired",
    );

    await expect(
      page.getByRole("heading", { name: "Link not accepted" }),
    ).toBeVisible();
    await expect(page.locator("main").getByRole("alert")).toContainText(
      "Email link is invalid or has expired",
    );
  });

  test("requests a recovery email from the sign-in form", async ({ page }) => {
    let payload = null;
    let redirectTo = null;
    await page.route("**/auth/v1/recover*", async (route) => {
      if (route.request().method() === "OPTIONS") {
        await route.fulfill({ status: 204, headers: authHeaders() });
        return;
      }
      payload = route.request().postDataJSON();
      redirectTo = new URL(route.request().url()).searchParams.get(
        "redirect_to",
      );
      await route.fulfill({
        status: 200,
        headers: authHeaders(),
        body: "{}",
      });
    });

    await page.goto("/");
    await page
      .locator("header")
      .getByRole("button", { name: "Sign In" })
      .click();
    await page.getByTestId("sign-in-email").fill("owner@example.test");
    await page.getByTestId("forgot-password").click();

    await expect(page.getByRole("status")).toContainText(
      "If an account exists for that address",
    );
    expect(payload).toEqual({ email: "owner@example.test" });
    expect(redirectTo).toMatch(/\/auth\/callback$/);
  });
});
